
class Solution {
public:
    vector<int> assignTasks(vector<int>& servers, vector<int>& tasks) {

            int n = servers.size();
                    int m = tasks.size();

                            // {weight, server_index}
                                    priority_queue<
                                                pair<int, int>,
                                                            vector<pair<int, int>>,
                                                                        greater<pair<int, int>>
                                                                                > free;

                                                                                        // {finish_time, weight, server_index}
                                                                                                priority_queue<
                                                                                                            tuple<long long, int, int>,
                                                                                                                        vector<tuple<long long, int, int>>,
                                                                                                                                    greater<tuple<long long, int, int>>
                                                                                                                                            > busy;

                                                                                                                                                    // Initially all servers are free
                                                                                                                                                            for (int i = 0; i < n; i++) {
                                                                                                                                                                        free.push({servers[i], i});
                                                                                                                                                                                }

                                                                                                                                                                                        vector<int> ans(m);

                                                                                                                                                                                                long long time = 0;

                                                                                                                                                                                                        for (int j = 0; j < m; j++) {

                                                                                                                                                                                                                    time = max(time, (long long)j);

                                                                                                                                                                                                                                // Release all servers that have finished
                                                                                                                                                                                                                                            while (!busy.empty() && get<0>(busy.top()) <= time) {

                                                                                                                                                                                                                                                            auto [finish, weight, index] = busy.top();
                                                                                                                                                                                                                                                                            busy.pop();

                                                                                                                                                                                                                                                                                            free.push({weight, index});
                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                    // If no server is free, wait
                                                                                                                                                                                                                                                                                                                                if (free.empty()) {

                                                                                                                                                                                                                                                                                                                                                time = get<0>(busy.top());

                                                                                                                                                                                                                                                                                                                                                                // Release all servers finishing at this time
                                                                                                                                                                                                                                                                                                                                                                                while (!busy.empty() && get<0>(busy.top()) <= time) {

                                                                                                                                                                                                                                                                                                                                                                                                    auto [finish, weight, index] = busy.top();
                                                                                                                                                                                                                                                                                                                                                                                                                        busy.pop();

                                                                                                                                                                                                                                                                                                                                                                                                                                            free.push({weight, index});
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Select server with minimum weight, then minimum index
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                auto [weight, index] = free.top();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            free.pop();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ans[j] = index;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Assign task and calculate finishing time
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                busy.push({time + tasks[j], weight, index});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return ans;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    